1800	// ---------------------------------------------------------------------------
1801	// 批量原子改期（按本地清单一次交换多项预约的时段/资源）
1802	// ---------------------------------------------------------------------------
1803	
1804	interface BatchTarget {
1805	  index: number; // 清单中的 0 基序号
1806	  booking: BookingRec;
1807	  startRaw: string;
1808	  endRaw: string;
1809	  startMin: number;
1810	  endMin: number;
1811	  resourceIds: string[]; // 已校验、按标识排序，整体替换原集合
1812	}
1813	
1814	// 读取清单文件：不可读、不是合法 JSON 均明确失败（绝不按空清单处理）
1815	async function loadManifest(file: string): Promise<unknown> {
1816	  let text: string;
1817	  try {
1818	    text = await readFile(file, 'utf8');
1819	  } catch (err) {
1820	    throw new BizError(`无法读取改期清单 ${file}: ${(err as Error).message}`);
1821	  }
1822	  try {
1823	    return JSON.parse(text);
1824	  } catch (err) {
1825	    throw new BizError(`改期清单 ${file} 已损坏，不是合法 JSON：${(err as Error).message}`);
1826	  }
1827	}
1828	
1829	// 清单结构（与数据文件无关的纯类型校验）；返回逐项原始记录
1830	function parseManifestShape(raw: unknown, file: string): Array<Record<string, unknown>> {
1831	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
1832	    throw new BizError(`改期清单 ${file} 内容非法：顶层必须是对象，形如 {"items": [...]}`);
1833	  }
1834	  const o = raw as Record<string, unknown>;
1835	  for (const k of Object.keys(o)) {
1836	    if (k !== 'items') throw new BizError(`改期清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items`);
1837	  }
1838	  if (!Array.isArray(o.items)) {
1839	    throw new BizError(`改期清单 ${file} 内容非法：items 必须是非空数组`);
1840	  }
1841	  const items = o.items as unknown[];
1842	  if (items.length === 0) throw new BizError(`改期清单 ${file} 为空：items 至少包含一项改期安排`);
1843	
1844	  const problems: string[] = [];
1845	  const records: Array<Record<string, unknown> | null> = [];
1846	  items.forEach((it, idx) => {
1847	    const at = `第 ${idx + 1} 项`;
1848	    if (typeof it !== 'object' || it === null || Array.isArray(it)) {
1849	      problems.push(`${at} 必须是对象`);
1850	      records.push(null);
1851	      return;
1852	    }
1853	    const rec = it as Record<string, unknown>;
1854	    for (const k of Object.keys(rec)) {
1855	      if (k !== 'bookingId' && k !== 'start' && k !== 'end' && k !== 'resourceIds') {
1856	        problems.push(`${at} 存在未知字段 “${k}”（只允许 bookingId、start、end、resourceIds）`);
1857	      }
1858	    }
1859	    if (typeof rec.bookingId !== 'string' || rec.bookingId === '') {
1860	      problems.push(`${at} 的 bookingId 必须是非空字符串`);
1861	    }
1862	    if (typeof rec.start !== 'string' || rec.start === '') {
1863	      problems.push(`${at} 的 start 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1864	    }
1865	    if (typeof rec.end !== 'string' || rec.end === '') {
1866	      problems.push(`${at} 的 end 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1867	    }
1868	    if (!Array.isArray(rec.resourceIds)) {
1869	      problems.push(`${at} 的 resourceIds 必须是非空数组（完整目标资源集合，整体替换原集合）`);
1870	    } else {
1871	      if (rec.resourceIds.length === 0) problems.push(`${at} 的 resourceIds 不能为空：资源集合整体替换，至少一个资源`);
1872	      rec.resourceIds.forEach((rid, j) => {
1873	        if (typeof rid !== 'string' || rid === '') {
1874	          problems.push(`${at}.resourceIds[${j}] 必须是非空资源标识字符串`);
1875	        }
1876	      });
1877	    }
1878	    records.push(rec);
1879	  });
1880	  if (problems.length > 0) {
1881	    throw new BizError(`改期清单 ${file} 内容非法，整批拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
1882	  }
1883	  return records as Array<Record<string, unknown>>;
1884	}
1885	
1886	async function cmdRescheduleBatch(args: string[]): Promise<void> {
1887	  const {values, positionals} = parseFlags(args, []);
1888	  if (values.size > 0) {
1889	    throw new UsageError(
1890	      `reschedule-batch 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`,
1891	    );
1892	  }
1893	  if (positionals.length !== 1) {
1894	    throw new UsageError('用法: reschedule-batch <改期清单文件>');
1895	  }
1896	  const manifestFile = positionals[0];
1897	
1898	  const file = activeDataFile;
1899	  const store = await loadStoreForWrite(file);
1900	  const records = parseManifestShape(await loadManifest(manifestFile), manifestFile);
1901	
1902	  // 第一阶段：逐项做与业务数据相关的基础校验，收集全部问题后一次性拒绝整批
1903	  const problems: string[] = [];
1904	  const seenBooking = new Map<string, number>(); // 标识 -> 首次出现的序号（1 基）
1905	  const planned: Array<BatchTarget | null> = [];
1906	  records.forEach((rec, idx) => {
1907	    const at = `第 ${idx + 1} 项（${rec.bookingId as string}）`;
1908	    let ok = true;
1909	
1910	    const firstAt = seenBooking.get(rec.bookingId as string);
1911	    if (firstAt !== undefined) {
1912	      problems.push(`${at} 预约标识重复：该标识已在第 ${firstAt} 项出现，每项预约在清单中只能出现一次`);
1913	      ok = false;
1914	    } else {
1915	      seenBooking.set(rec.bookingId as string, idx + 1);
1916	    }
1917	
1918	    const booking = store.bookings.find((b) => b.id === rec.bookingId);
1919	    if (!booking) {
1920	      problems.push(`${at} 未知预约标识: ${rec.bookingId}`);
1921	      ok = false;
1922	    } else if (booking.status === 'cancelled') {
1923	      problems.push(`${at} 预约 ${booking.id} 已取消，不能改期`);
1924	      ok = false;
1925	    }
1926	
1927	    const rawRids = rec.resourceIds as string[];
1928	    const dupes = rawRids.filter((id, j) => rawRids.indexOf(id) !== j);
