253	// ---------------------------------------------------------------------------
254	// 数据模型与文件存取
255	// ---------------------------------------------------------------------------
256	
257	type ResourceType = 'venue' | 'equipment' | 'person';
258	type BookingStatus = 'active' | 'cancelled';
259	type WaitlistStatus = 'waiting' | 'fulfilled' | 'cancelled';
260	type WaitlistKind = 'fixed' | 'flexible'; // 固定时段候补 / 弹性时段候补
261	type ClosureStatus = 'active' | 'cancelled';
262	type BatchOpStatus = 'active' | 'undone'; // 批量改期操作：未撤销 / 已撤销
263	
264	interface ResourceRec {
265	  id: string;
