2080	// ---------------------------------------------------------------------------
2081	// 批量改期操作记录：查询与安全撤销
2082	// 快照只描述该次提交的前后安排；之后其他入口造成的现状变化不算损坏，
2083	// 撤销时按“当前值”与记录的改期后安排逐项核对。
2084	// ---------------------------------------------------------------------------
2085	
2086	const BATCH_OP_STATUS_LABEL: Record<BatchOpStatus, string> = {
2087	  active: '未撤销',
2088	  undone: '已撤销',
2089	};
2090	
2091	// 判断预约当前安排是否与某一快照完全一致（时间 + 完整资源集合，资源均已排序）
2092	function arrangementMatches(b: BookingRec, side: BatchOpItem['before']): boolean {
2093	  return (
2094	    b.start === side.start &&
2095	    b.end === side.end &&
2096	    b.resourceIds.length === side.resourceIds.length &&
2097	    b.resourceIds.every((id, j) => id === side.resourceIds[j])
2098	  );
2099	}
2100	
2101	// 渲染单项的前后安排（系列归属在首行给出）
2102	function renderBatchOpItem(store: Store, item: BatchOpItem, index: number, indent: string): string[] {
2103	  const lines = [
2104	    `${indent}第 ${index + 1} 项 ${item.bookingId}` +
2105	      (item.seriesId !== undefined ? `（系列 ${item.seriesId}）` : ''),
2106	  ];
2107	  lines.push(`${indent}  改期前: ${item.before.start} → ${item.before.end}`);
2108	  lines.push(`${indent}    资源: ${formatResourceIds(store, item.before.resourceIds)}`);
2109	  lines.push(`${indent}  改期后: ${item.after.start} → ${item.after.end}`);
2110	  lines.push(`${indent}    资源: ${formatResourceIds(store, item.after.resourceIds)}`);
2111	  return lines;
2112	}
2113	
2114	async function cmdListBatchOps(args: string[]): Promise<void> {
2115	  const {values, positionals} = parseFlags(args, []);
2116	  if (values.size > 0) {
2117	    throw new UsageError(
2118	      `list-batch-ops 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`,
2119	    );
2120	  }
2121	  if (positionals.length > 0) {
2122	    throw new UsageError(`list-batch-ops 不接受位置参数: ${positionals.join(' ')}`);
2123	  }
2124	
2125	  const store = await loadStore(activeDataFile);
2126	  if (store.batchOps.length === 0) {
2127	    console.log(
2128	      '暂无批量改期操作记录（无变化提交不建记录；可用 reschedule-batch 提交批量改期，undo-batch-op <操作标识> 撤销）。',
2129	    );
2130	    return;
2131	  }
2132	  // 记录按标识序号（即成功提交先后）加载与展示；项按提交顺序
2133	  const undone = store.batchOps.filter((o) => o.status === 'undone').length;
2134	  console.log(
2135	    `批量改期操作记录（共 ${store.batchOps.length} 条，按操作先后；未撤销 ${store.batchOps.length - undone} 条，已撤销 ${undone} 条）：`,
2136	  );
2137	  for (const op of store.batchOps) {
2138	    console.log(`- ${op.id} [${BATCH_OP_STATUS_LABEL[op.status]}]（${op.items.length} 项，按提交顺序）`);
2139	    op.items.forEach((item, i) => {
2140	      console.log(renderBatchOpItem(store, item, i, '    ').join('\n'));
2141	    });
2142	  }
2143	}
2144	
2145	async function cmdUndoBatchOp(args: string[]): Promise<void> {
2146	  const {values, positionals} = parseFlags(args, []);
2147	  if (values.size > 0) {
2148	    throw new UsageError(
2149	      `undo-batch-op 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`,
2150	    );
2151	  }
2152	  if (positionals.length !== 1) {
2153	    throw new UsageError('用法: undo-batch-op <批量改期操作标识>');
2154	  }
2155	  const opId = positionals[0];
2156	  if (!/^O\d{4,}$/.test(opId)) throw new BizError(`批量改期操作标识非法: ${opId}`);
2157	
2158	  const file = activeDataFile;
2159	  const store = await loadStoreForWrite(file);
2160	  const op = store.batchOps.find((x) => x.id === opId);
2161	  if (!op) throw new BizError(`未知批量改期操作标识: ${opId}`);
2162	
2163	  if (op.status === 'undone') {
2164	    // 幂等：重复撤销已撤销记录成功且不触碰当前安排——即使之后又有改期
2165	    console.log(`操作 ${opId} 已是撤销状态，未做任何改动（当前安排保持不变）。`);
2166	    return;
2167	  }
2168	
2169	  // 前置一致性：全部涉及预约须仍有效，且当前时间、资源集合、系列归属与该记录的
2170	  // 改期后安排完全一致；按当前值比对，期间改动后又恢复一致仍可撤销。
2171	  // 任一不一致即整笔拒绝并列出全部不一致预约。
2172	  const mismatches: string[] = [];
2173	  const involved = new Map<string, {booking: BookingRec; item: BatchOpItem; index: number}>();
2174	  op.items.forEach((item, index) => {
2175	    const b = store.bookings.find((x) => x.id === item.bookingId);
2176	    if (!b) {
2177	      mismatches.push(`第 ${index + 1} 项 ${item.bookingId}：预约记录不存在（数据可能已损坏）`);
2178	      return;
2179	    }
2180	    if (b.status === 'cancelled') {
2181	      mismatches.push(`第 ${index + 1} 项 ${b.id}：预约已取消，撤销不能复活已取消预约`);
2182	      return;
2183	    }
2184	    involved.set(b.id, {booking: b, item, index});
2185	    const reasons: string[] = [];
2186	    if (!arrangementMatches(b, item.after)) {
2187	      reasons.push(
2188	        `当前安排（${b.start} → ${b.end}；资源 ${b.resourceIds.join('、')}）` +
2189	          `与记录改期后安排（${item.after.start} → ${item.after.end}；资源 ${item.after.resourceIds.join('、')}）不一致`,
2190	      );
2191	    }
2192	    const curSeries = b.seriesId;
2193	    const recSeries = item.seriesId;
2194	    if (curSeries !== recSeries) {
2195	      reasons.push(
2196	        `当前系列归属 ${curSeries ?? '无'} 与记录的系列归属 ${recSeries ?? '无'} 不一致`,
2197	      );
2198	    }
2199	    if (reasons.length > 0) {
2200	      mismatches.push(`第 ${index + 1} 项 ${b.id}：` + reasons.join('；'));
2201	    }
2202	  });
2203	
2204	  if (mismatches.length > 0) {
2205	    throw new BizError(
2206	      `撤销 ${opId} 被拒绝：存在 ${mismatches.length} 项涉及预约的当前状态与该记录改期后安排不一致` +
2207	        '（整笔不变，未恢复任何安排、未改变记录状态）：\n' +
2208	        mismatches.map((m) => `- ${m}`).join('\n'),
2209	    );
2210	  }
2211	
2212	  // 可行性：对“整笔恢复后”的最终安排做统一批次校验（无写入副作用）。
2213	  // 本操作涉及预约的当前占用一律排除（允许互换时段）；
2214	  // 障碍只来自本操作之外的有效预约，以及各项恢复安排彼此之间。
2215	  const involvedIds = new Set(op.items.map((it) => it.bookingId));
2216	  const targets = op.items.map((item) => ({
2217	    startMin: parseDateTime(item.before.start, '恢复开始时间'),
2218	    endMin: parseDateTime(item.before.end, '恢复结束时间'),
2219	    resourceIds: item.before.resourceIds,
2220	  }));
2221	  const failures = validateBatchTargets(store, targets, involvedIds);
2222	
2223	  if (failures.length > 0) {
2224	    // 按提交顺序报告全部失败项；批内冲突在双方项中都会出现
2225	    const blocks = failures.map((f) => {
2226	      const item = op.items[f.index];
2227	      const lines = [
2228	        `第 ${f.index + 1} 项 ${item.bookingId} 恢复为 ${item.before.start} → ${item.before.end}：`,
2229	      ];
2230	      if (f.gaps.length > 0) {
2231	        lines.push('  开放不足资源:');
2232	        lines.push(...gapLines(f.gaps, '    '));
2233	      }
2234	      if (f.external.length + f.internal.length > 0) {
2235	        lines.push('  冲突预约:');
2236	        for (const c of f.external) {
2237	          lines.push(
2238	            `    - ${c.booking.id}（${c.booking.start} → ${c.booking.end}）` +
2239	              `：共同资源 ${formatResourceIds(store, c.shared)}`,
2240	          );
2241	        }
2242	        for (const x of f.internal) {
2243	          const o = op.items[x.otherIndex];
2244	          lines.push(
2245	            `    - ${o.bookingId}（本操作第 ${x.otherIndex + 1} 项恢复为 ${o.before.start} → ${o.before.end}）` +
2246	              `：共同资源 ${formatResourceIds(store, x.shared)}`,
2247	          );
2248	        }
2249	      }
2250	      return lines.join('\n');
2251	    });
2252	    throw new BizError(
2253	      `撤销 ${opId} 失败：共 ${failures.length} 项恢复安排不满足条件（按提交顺序），整笔未改动：\n${blocks.join('\n')}`,
2254	    );
