3161	// ---------------------------------------------------------------------------
3162	// 多项弹性预约的联合排程与原子创建（schedule-flex）
3163	//
3164	// 读取本地 JSON 清单（{"items": [...]}，非空、有顺序），每项给出营业地时间窗口、
3165	// 所需连续分钟数与有顺序的需求组（每组列出一个可任选其一的候选资源数组）。
3166	// 为整份清单寻找同时可行的安排：每项完整落在自身窗口内，每组恰选一个候选，
3167	// 一项所选资源互不相同并全程固定（不换资源、不拼接间断）；新项之间仅共同资源
3168	// 的左闭右开时间重叠才冲突，端点相接可行。多个完整方案按清单顺序逐项比较：
3169	// 先比该项开始分钟，再按需求组顺序以字符串字典序比资源标识，第一处差异取
3170	// 较小者，随后才比较下一项（清单顺序只用于取舍，不限定活动发生先后）。
3171	// 有解时按清单顺序各创建一项普通预约（稳定、不复用标识，不加入系列、不改动
3172	// 既有预约与候补、不自动处理候补），原子保存全部预约后才报告成功；无整体解
3173	// 明确提示并退出 1，不保存部分方案。每次提交都是新的创建请求，不按清单路径
3174	// 或内容去重。
3175	//
3176	// 求解不逐项贪选最早：项 i 的开始分钟若被项 j 的占用“顶住”，则 s_i = s_j + d_j，
3177	// 故候选开始分钟取“基础空闲段起点”与“其他项占用结束（s_j + d_j）”的闭包
3178	// （仅候选资源集合有交集的项之间传播；按开始分钟归纳，最小方案的每个开始都
3179	// 落在该闭包内）。随后按清单顺序深度优先逐项试探：开始分钟升序、同一开始的
3180	// 资源序列按字典序升序枚举，首个完整方案即按上述比较的最小方案——不会因为
3181	// 逐项固定最早选择而漏掉须调整前项时间或资源的解，也不跳过受阻项。
3182	// ---------------------------------------------------------------------------
3183	
3184	interface FlexPlanItem {
3185	  index: number; // 1 基清单序号
3186	  startRaw: string; // 窗口开始（YYYY-MM-DDTHH:mm）
3187	  endRaw: string; // 窗口结束
3188	  startMin: number;
3189	  endMin: number;
3190	  duration: number; // 所需连续分钟数（正整数，不超过窗口长度）
3191	  groups: RequirementGroup[]; // 有顺序的需求组，每组恰选一个候选
3192	}
3193	
3194	interface FlexPlacement {
3195	  startMin: number;
3196	  endMin: number;
3197	  picks: string[]; // 按需求组顺序的所选资源
3198	}
3199	
3200	// 读取预约清单文件：不可读、不是合法 JSON 均明确失败（绝不按空清单处理）
3201	async function loadFlexManifest(file: string): Promise<unknown> {
3202	  let text: string;
3203	  try {
3204	    text = await readFile(file, 'utf8');
3205	  } catch (err) {
3206	    throw new BizError(`无法读取预约清单 ${file}: ${(err as Error).message}`);
3207	  }
3208	  try {
3209	    return JSON.parse(text);
3210	  } catch (err) {
3211	    throw new BizError(`预约清单 ${file} 已损坏，不是合法 JSON：${(err as Error).message}`);
3212	  }
3213	}
3214	
3215	// 清单结构（与业务数据无关的纯类型校验）；返回逐项原始记录
3216	function parseFlexPlanShape(raw: unknown, file: string): Array<Record<string, unknown>> {
3217	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
3218	    throw new BizError(`预约清单 ${file} 内容非法：顶层必须是对象，形如 {"items": [...]}`);
3219	  }
3220	  const o = raw as Record<string, unknown>;
3221	  for (const k of Object.keys(o)) {
3222	    if (k !== 'items') throw new BizError(`预约清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items`);
3223	  }
3224	  if (!Array.isArray(o.items)) {
3225	    throw new BizError(`预约清单 ${file} 内容非法：items 必须是非空数组`);
3226	  }
3227	  const items = o.items as unknown[];
3228	  if (items.length === 0) throw new BizError(`预约清单 ${file} 为空：items 至少包含一项预约请求`);
3229	
3230	  const problems: string[] = [];
3231	  const records: Array<Record<string, unknown> | null> = [];
3232	  items.forEach((it, idx) => {
3233	    const at = `第 ${idx + 1} 项`;
3234	    if (typeof it !== 'object' || it === null || Array.isArray(it)) {
3235	      problems.push(`${at} 必须是对象`);
3236	      records.push(null);
3237	      return;
3238	    }
3239	    const rec = it as Record<string, unknown>;
3240	    for (const k of Object.keys(rec)) {
3241	      if (k !== 'window' && k !== 'duration' && k !== 'groups') {
3242	        problems.push(`${at} 存在未知字段 “${k}”（只允许 window、duration、groups）`);
3243	      }
3244	    }
3245	    if (typeof rec.window !== 'string' || rec.window === '') {
3246	      problems.push(`${at} 的 window 必须是 窗口开始/窗口结束 形式的非空字符串`);
3247	    }
3248	    if (typeof rec.duration !== 'number' || !Number.isInteger(rec.duration) || rec.duration <= 0) {
3249	      problems.push(`${at} 的 duration 必须是正整数分钟（不超过窗口长度）`);
3250	    }
3251	    if (!Array.isArray(rec.groups) || rec.groups.length === 0) {
3252	      problems.push(`${at} 的 groups 必须是非空数组（至少一个有顺序的需求组）`);
3253	    } else {
3254	      rec.groups.forEach((g, gi) => {
3255	        if (!Array.isArray(g) || g.length === 0) {
3256	          problems.push(`${at} 第 ${gi + 1} 需求组必须是非空数组（可任选其一的候选资源标识）`);
3257	        } else {
3258	          g.forEach((id) => {
3259	            if (typeof id !== 'string' || id === '') {
3260	              problems.push(`${at} 第 ${gi + 1} 需求组含非法候选：候选资源标识必须是非空字符串`);
3261	            }
3262	          });
3263	        }
3264	      });
3265	    }
3266	    records.push(rec);
3267	  });
3268	  if (problems.length > 0) {
3269	    throw new BizError(`预约清单 ${file} 内容非法，整单拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
3270	  }
3271	  return records as Array<Record<string, unknown>>;
3272	}
3273	
3274	// 逐项做与业务数据相关的校验（窗口真实有效、时长不超过窗口、组内重复与未知资源），
3275	// 收集全部问题后一次性拒绝整单；通过则返回排程项
3276	function parseFlexPlanItems(store: Store, records: Array<Record<string, unknown>>, file: string): FlexPlanItem[] {
3277	  const problems: string[] = [];
3278	  const items: Array<FlexPlanItem | null> = records.map((rec, idx) => {
3279	    const at = `第 ${idx + 1} 项`;
3280	    let ok = true;
3281	
3282	    let win: {start: string; end: string; startMin: number; endMin: number} | null = null;
3283	    try {
3284	      win = parseFlexWindow(rec.window as string, `${at}窗口`);
3285	    } catch (err) {
3286	      if (err instanceof BizError) {
3287	        problems.push(err.message);
3288	        ok = false;
3289	      } else {
3290	        throw err;
3291	      }
3292	    }
3293	
3294	    const duration = rec.duration as number; // 结构校验已保证正整数
3295	    if (win !== null && duration > win.endMin - win.startMin) {
3296	      problems.push(
3297	        `${at} 所需连续时长 ${duration} 分钟超过窗口长度 ${win.endMin - win.startMin} 分钟` +
3298	          `（窗口: ${win.start} → ${win.end}）`,
3299	      );
3300	      ok = false;
3301	    }
3302	
3303	    const groups: RequirementGroup[] = [];
3304	    (rec.groups as string[][]).forEach((ids, gi) => {
3305	      const glabel = `${at} 第 ${gi + 1} 需求组`;
3306	      const seen = new Set<string>();
3307	      const dupes: string[] = [];
3308	      for (const id of ids) {
3309	        if (seen.has(id) && !dupes.includes(id)) dupes.push(id);
3310	        seen.add(id);
3311	      }
3312	      if (dupes.length > 0) {
3313	        problems.push(`${glabel}内候选资源重复: ${dupes.join('、')}`);
3314	        ok = false;
3315	      }
3316	      const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
3317	      if (unknown.length > 0) {
3318	        problems.push(`${glabel}含未知资源标识: ${unknown.join('、')}`);
3319	        ok = false;
3320	      }
3321	      groups.push({index: gi + 1, candidates: [...seen].sort()});
3322	    });
3323	
3324	    if (!ok || win === null) return null;
3325	    return {
3326	      index: idx + 1,
3327	      startRaw: win.start,
3328	      endRaw: win.end,
3329	      startMin: win.startMin,
3330	      endMin: win.endMin,
3331	      duration,
3332	      groups,
3333	    };
3334	  });
3335	  if (problems.length > 0) {
3336	    throw new BizError(`预约清单 ${file} 内容非法，整单拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
3337	  }
