410	  ok(
411	    df,
412	    ['add-waitlist', '--resource', 'R0001', '--start', '2026-10-12T11:00', '--end', '2026-10-12T12:00'],
413	    '未兑现候补 W0001',
414	  );
415	
416	  // 最早可行：09:00 → 10:00（取消记录不阻挡，结束与 B0002 起点相接）
417	  const m = writeManifest(dir, 'plan.json', [
418	    {window: '2026-10-12T09:00/2026-10-12T12:00', duration: 60, groups: [['R0001']]},
419	  ]);
420	  const r = scheduleFlex(df, m, '占用口径');
421	  assertPlan(r, [{id: 'B0003', start: '2026-10-12T09:00', end: '2026-10-12T10:00', picks: ['R0001']}], '占用口径');
422	
423	  // 候补不被自动处理：仍为等待中
424	  const store = readStore(df);
425	  assert.equal(store.waitlist.length, 1, '不创建额外候补');
426	  assert.equal(store.waitlist[0].status, 'waiting', '不自动处理候补');
427	  assert.equal(store.waitlist[0].bookingId, undefined, '候补无兑现关联');
428	});
429	
430	// ---------------------------------------------------------------------------
431	// 7. 真实保存失败与重试：退出 1、原文件逐字节保留、标识未消费；换可写位置重试成功
432	// ---------------------------------------------------------------------------
433	
434	test('保存失败：退出 1 且原数据逐字节保留，同一原数据重试成功且标识未消费', (t) => {
435	  const dir = tempDir(t);
436	  const df = join(dir, 'data.json');
437	  addResource(df, '甲'); // R0001
438	  const manifest = writeManifest(dir, 'plan.json', [
439	    {window: '2026-10-12T09:00/2026-10-12T10:00', duration: 60, groups: [['R0001']]},
440	  ]);
441	
442	  // 同一原数据放到保存必然失败的位置（文件名 255 字节，临时文件名超限）
443	  const origBytes = readFileSync(df);
444	  const longFile = join(dir, LONG_NAME);
445	  writeFileSync(longFile, origBytes);
446	  const r = bizFail(longFile, ['schedule-flex', manifest], '保存失败');
447	  assert.match(r.stderr, /保存数据文件 .* 失败/, '说明保存失败原因');
448	  assert.ok(!r.stdout.includes('联合排程成功'), '不报告成功');
449	  assertFileBytes(longFile, origBytes, '保存失败逐字节保留');
450	  const store = readStore(longFile);
451	  assert.equal(store.bookings.length, 0, '不产生预约记录');
452	  assert.equal(store.bookingSeq, 0, '标识计数不变');
453	
454	  // 在可保存的位置用同一原数据重试：成功且标识未被失败尝试消费
