458	  assertPlan(r2, [{id: 'B0001', start: '2026-10-12T09:00', end: '2026-10-12T10:00', picks: ['R0001']}], '重试标识未消费');
459	  assertBooking(retryFile, 'B0001', '2026-10-12T09:00', '2026-10-12T10:00', ['R0001'], '重试生效');
460	});
